/* r4b1t motion compatibility shim + dual-shell loader */
(function(){
  'use strict';
  function list(targets){
    if(!targets)return[];
    if(typeof targets==='string')return Array.from(document.querySelectorAll(targets));
    if(typeof Element!=='undefined'&&targets instanceof Element)return[targets];
    if(typeof targets.length==='number')return Array.from(targets);
    return[];
  }
  function last(value,el){
    var result=Array.isArray(value)?value[value.length-1]:value;
    if(typeof result==='function')result=result(el);
    return result;
  }
  function apply(el,props){
    if(!el||!props)return;
    var transforms=[];
    var tx=last(props.translateX,el),ty=last(props.translateY,el),scale=last(props.scale,el),rotate=last(props.rotate,el);
    if(tx!==undefined)transforms.push('translateX('+tx+'px)');
    if(ty!==undefined)transforms.push('translateY('+ty+'px)');
    if(scale!==undefined)transforms.push('scale('+scale+')');
    if(rotate!==undefined)transforms.push('rotate('+rotate+'deg)');
    if(transforms.length&&el.style)el.style.transform=transforms.join(' ');
    ['opacity','backgroundColor','color','maxHeight','strokeDashoffset'].forEach(function(key){
      var value=last(props[key],el);
      if(value===undefined||!el.style)return;
      if(key==='maxHeight'&&typeof value==='number')value=value+'px';
      el.style[key]=String(value);
    });
  }
  function anime(options){
    options=options||{};
    var targets=list(options.targets);
    var duration=Math.max(0,Number(options.duration)||0);
    var delay=typeof options.delay==='number'?Math.max(0,options.delay):0;
    var timer=setTimeout(function(){
      targets.forEach(function(el){apply(el,options);});
      if(typeof options.complete==='function')options.complete();
    },duration+delay);
    return{pause:function(){clearTimeout(timer);}};
  }
  anime.remove=function(){};
  anime.set=function(targets,props){list(targets).forEach(function(el){apply(el,props||{});});};
  anime.stagger=function(step){
    step=Number(step)||0;
    return function(_el,index){return index*step;};
  };
  window.anime=anime;
  document.write('<link rel="stylesheet" href="dual-shell.css"><script defer src="dual-shell.js"><\/script>');
})();
